 	key = strings.ReplaceAll(key, " ", "_")
-	// Flattened-config exporters (Spring, dotnet, Hashicorp Vault) emit dotted keys
-	// like "db.password" or "mysql.root.password"; treat them like underscored.
-	key = strings.ReplaceAll(key, ".", "_")
 	return key
 }
